"""Parser for Meridian CRM 4.2 batch_jobs.cfg schedules."""

import re


_JOB_LINE = re.compile(
    r"^JOB (?P<name>\S+) AT (?P<at>(?:[01]\d|2[0-3]):[0-5]\d) "
    r"RUN (?P<script>\S+\.crms)"
    r"(?: ON_ERROR (?P<error>ABORT|CONTINUE|RETRY:\d+))?$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a legacy batch schedule, preserving JOB line order."""
    schedule: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()

        if not line or line.startswith("#"):
            continue

        match = _JOB_LINE.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid batch job line {line_number}: {raw_line!r}")

        error_clause = match.group("error")
        if error_clause is None or error_clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif error_clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {
                "policy": "RETRY",
                "retries": int(error_clause.removeprefix("RETRY:")),
            }

        schedule.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
